export const Autohide: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [show, setShow] = React.useState(false);
    const [duration, setDuration] = React.useState(1);
    const showNotification = (duration: number) => {
      setDuration(duration);
      setShow(true);
    };
    return (
      <Inline spacing="2-x">
        <Stack spacing="3-x">
          <Button variant="primary" onClick={() => showNotification(1)}>
            Show 1 sec notification
          </Button>
          <Button variant="primary" onClick={() => showNotification(5)}>
            Show 5 sec notification
          </Button>
        </Stack>
        {show && (
          <Toast
            allowClose
            autoHideDuration={duration * 1000}
            title="New Features"
            time="2:35 pm"
            onClose={() => setShow(false)}
          >
            We have some great new features to show you.{" "}
            <Link
              size="small"
              href="#"
              inline
              onClick={(e: React.MouseEvent<HTMLAnchorElement>) =>
                e.preventDefault()
              }
            >
              Let's go
            </Link>
          </Toast>
        )}
      </Inline>
    );
  },
};
